# Code generated by Claude
"""
Diagnosis of the moved layout's place failure (David 2026-10-25; no setting changes): the same selection and episode as stance_select_moved_test.py, with a source that logs, per orchestrator segment and
phase, the left arm's joint margins to their limits (smallest distance of any joint to its nearer limit, which joint), the pad's distance to the waypoint, and the clearance monitor's smallest distances.
Stops the episode shortly after the first failure.

    MUJOCO_GL=egl python experiments/moved_place_diag.py
"""
import json
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from episode_test_sources import make_clearance_monitor  # noqa: E402
from src.episode_runner import run_episode  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from stance_select_moved_test import MOVED  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402


def main():
    task = make_pipeline_task(PLAN4, task_cfg=MOVED, stance_mode="bench_region")
    sim = load_task(MOVED, cameras=True)
    m, d = sim.model, sim.data
    ids = arm_ids(m, "left")
    qadr = np.asarray(ids["qadr"])
    jids = [int(np.where(m.jnt_qposadr == a)[0][0]) for a in qadr]
    lo, hi = m.jnt_range[jids, 0], m.jnt_range[jids, 1]
    S = {"margin": {}, "n": 0}
    mon = {}

    def extra(mm, dd):
        mon["m"] = make_clearance_monitor(mm, dd)

        def step(obs):
            S["n"] += 1
            ep = obs.get("policy")
            orch = task["pipeline"].get("orchestrator")
            if not ep or not orch:
                return None
            seg = sum(1 for x in orch["state"]["status"] if x == "done")
            q = dd.qpos[qadr]
            marg = np.minimum(q - lo, hi - q)
            j = int(np.argmin(marg))
            r = S["margin"].setdefault(f"seg{seg}|{ep['phase']}", {"min_margin_rad": 9.0})
            if marg[j] < r["min_margin_rad"]:
                r.update(min_margin_rad=float(marg[j]), joint=j + 1, q=float(q[j]), lo=float(lo[j]), hi=float(hi[j]), t_s=float(dd.time))
            return None
        return {"clearance": mon["m"], "margins": {"name": "margins", "step": step}}

    s = run_episode(task, m, d, out_dir=PROJECT_ROOT / "data" / "moved_place_diag" / "episode", extra_sources=extra, stop_after_handoff_s=None)
    print("outcome", s["outcome"])
    out = {"joint_margins": S["margin"], "clearance": {k: v for k, v in mon["m"]["state"]["min"].items()}, "joint_limits": {"lo": lo.tolist(), "hi": hi.tolist()}}
    Path("docs/reports/logs").mkdir(parents=True, exist_ok=True)
    tmp = Path("docs/reports/logs/moved_place_diag.json.tmp")
    tmp.write_text(json.dumps(out, indent=1, default=str))
    tmp.replace(Path("docs/reports/logs/moved_place_diag.json"))
    for k in sorted(S["margin"]):
        if k.startswith(("seg3", "seg4")) or "PLACE" in k or "OVER" in k:
            print(k, {a: (round(b, 4) if isinstance(b, float) else b) for a, b in S["margin"][k].items()})
    for ph, groups in mon["m"]["state"]["min"].items():
        if "PLACE" in ph or "OVER" in ph:
            print(ph, {g: (round(1000 * v[0], 1), v[1], v[2]) for g, v in groups.items()})


if __name__ == "__main__":
    main()
